def lgraph(pts, ylab, xlab, xt, yt, marks='', w=300, h=170):
    """간단한 꺾은선 그래프 SVG. pts: [(x,y)] (0~10, 0~10 좌표)."""
    X = lambda x: 40 + x * (w - 60) / 10
    Y = lambda y: h - 30 - y * (h - 50) / 10
    poly = ' '.join(f'{X(x):.0f},{Y(y):.0f}' for x, y in pts)
    s = [f'<svg viewBox="0 0 {w} {h}" xmlns="http://www.w3.org/2000/svg" style="max-width:{w + 20}px">',
         '<style>.a{stroke:#1f2430;stroke-width:1.3}.t{font-size:11px;fill:#1f2430}.s{font-size:10px;fill:#5b6272}</style>',
         f'<line class="a" x1="40" y1="{h - 30}" x2="{w - 12}" y2="{h - 30}"/><line class="a" x1="40" y1="12" x2="40" y2="{h - 30}"/>',
         f'<text class="t" x="12" y="{h / 2}" transform="rotate(-90 12 {h / 2})" text-anchor="middle">{ylab}</text>',
         f'<text class="t" x="{w - 14}" y="{h - 6}" text-anchor="end">{xlab}</text>']
    for x, lab in xt:
        s.append(f'<text class="s" x="{X(x):.0f}" y="{h - 16}" text-anchor="middle">{lab}</text>')
    for y, lab in yt:
        s.append(f'<text class="s" x="34" y="{Y(y) + 4:.0f}" text-anchor="end">{lab}</text><line x1="40" x2="{w - 12}" y1="{Y(y):.0f}" y2="{Y(y):.0f}" stroke="#e3e6ec"/>')
    s.append(marks.replace('{X', '{').format(**{f'x{i}': X(i) for i in range(11)}) if marks else '')
    s.append(f'<polyline points="{poly}" fill="none" stroke="#d6453d" stroke-width="2.6"/></svg>')
    return ''.join(s)


def chrom(x, y, L, col, two=True):
    """세로 방향 염색체 (두 가닥이면 염색 분체 2개)."""
    if two:
        return (f'<rect x="{x - 5}" y="{y - L / 2}" width="4.5" height="{L}" rx="2.2" fill="{col}"/>'
                f'<rect x="{x + 0.5}" y="{y - L / 2}" width="4.5" height="{L}" rx="2.2" fill="{col}"/>'
                f'<rect x="{x - 5}" y="{y - 1.5}" width="10" height="3" fill="{col}"/>')
    return f'<rect x="{x - 2.3}" y="{y - L / 2}" width="4.6" height="{L}" rx="2.2" fill="{col}"/>'


def cell(cx, label, parts):
    body = ''.join(parts)
    return (f'<g><circle cx="{cx}" cy="70" r="54" fill="#fdf1e3" stroke="#e0b98a" stroke-width="2"/>'
            f'<line x1="{cx}" y1="18" x2="{cx}" y2="122" stroke="#d9c4a6" stroke-dasharray="3 3"/>{body}'
            f'<text x="{cx}" y="142" text-anchor="middle" font-size="12" font-weight="700">{label}</text></g>')


